        ? ['query', 'error', 'warn']
        : ['error'],
  });

if (process.env.NODE_ENV !== 'production') {
  globalForPrisma.prisma = prisma;
}

// Seed memoizado para evitar re-ejecución en cada request
export async function ensureSeed(): Promise<void> {
  if (globalForPrisma.seedPromise) {
    return globalForPrisma.seedPromise;
  }

  globalForPrisma.seedPromise = (async () => {
    const userCount = await prisma.user.count();
    if (userCount > 0) return;

    // Seed inicial solo si la DB está vacía
    console.log('[Seed] Base de datos vacía, ejecutando seed inicial...');
    // El seed real se ejecuta desde prisma/seed.ts
  })();

  return globalForPrisma.seedPromise;
}

// Helper para transacciones con retry
export async function withTransaction<T>(
  fn: (tx: PrismaClient) => Promise<T>,
  maxRetries = 3
): Promise<T> {
  let lastError: Error | null = null;

  for (let i = 0; i < maxRetries; i++) {
    try {
      return await prisma.$transaction(fn, {
        maxWait: 5000,
        timeout: 10000,
        isolationLevel: 'ReadCommitted',
      });
    } catch (error) {
      lastError = error as Error;
      if (i < maxRetries - 1) {
        await new Promise((resolve) =>
          setTimeout(resolve, Math.pow(2, i) * 100)
        );
      }
    }
  }

  throw lastError;
}
