runs_route = """// API route para obtener runs del usuario
import { NextRequest } from 'next/server';
import { prisma, ensureSeed } from '@/lib/prisma';
import { apiSuccess, apiError } from '@/lib/api-utils';
import { logger, logHttpRequest } from '@/lib/logger';

export async function GET(req: NextRequest) {
  const startTime = Date.now();

  try {
    await ensureSeed();

    const { searchParams } = new URL(req.url);
    const page = parseInt(searchParams.get('page') || '1');
    const pageSize = parseInt(searchParams.get('pageSize') || '20');
    const type = searchParams.get('type');
    const status = searchParams.get('status');

    // TODO: Obtener userId de la sesión
    const userId = 'demo-user';

    const where = {
      userId,
      ...(type && { type }),
      ...(status && { status }),
    };

    const [runs, total] = await Promise.all([
      prisma.run.findMany({
        where,
        include: {
          responses: true,
        },
        orderBy: { createdAt: 'desc' },
        skip: (page - 1) * pageSize,
        take: pageSize,
      }),
      prisma.run.count({ where }),
    ]);

    const response = {
      data: runs,
      total,
      page,
      pageSize,
      totalPages: Math.ceil(total / pageSize),
    };

    logHttpRequest('GET', '/api/runs', 200, Date.now() - startTime);

    return apiSuccess(response);
  } catch (error) {
    logger.error({ err: error }, 'Error in /api/runs');
    return apiError('Internal server error', 500);
  }
}
