import { NextRequest } from 'next/server';
import { prisma, ensureSeed } from '@/lib/prisma';
import { apiSuccess, apiError } from '@/lib/api-utils';
import { logger, logHttpRequest } from '@/lib/logger';

export async function GET(req: NextRequest) {
  const startTime = Date.now();

  try {
    await ensureSeed();

    // Obtener todos los tags únicos con su conteo
    const tags = await prisma.conversationTag.groupBy({
      by: ['tag'],
      _count: {
        tag: true,
      },
      orderBy: {
        _count: {
          tag: 'desc',
        },
      },
    });

    const response = tags.map((t) => ({
      name: t.tag,
      count: t._count.tag,
    }));

    logHttpRequest('GET', '/api/tags', 200, Date.now() - startTime);

    return apiSuccess(response);
  } catch (error) {
    logger.error({ err: error }, 'Error in /api/tags');
    return apiError('Internal server error', 500);
  }
}
"""
