middleware = """// Middleware de Next.js para autenticación y rate limiting
import { NextResponse } from 'next/server';
import type { NextRequest } from 'next/server';

// Rutas públicas que no requieren autenticación
const publicRoutes = [
  '/',
  '/login',
  '/register',
  '/api/auth',
  '/api/webhooks/stripe',
  '/api/health',
];

// Rutas de API que tienen rate limiting estricto
const apiRoutes = ['/api/chat', '/api/images', '/api/vision', '/api/tts'];

export function middleware(request: NextRequest) {
  const { pathname } = request.nextUrl;

  // Verificar si es ruta pública
  const isPublic = publicRoutes.some(
    (route) => pathname === route || pathname.startsWith(route + '/')
  );

  // Verificar si es ruta de API
  const isApi = apiRoutes.some((route) => pathname.startsWith(route));

  // Rate limiting para APIs
  if (isApi) {
    const ip = request.headers.get('x-forwarded-for') || 'unknown';
    const rateLimitKey = `rate-limit:${ip}:${pathname}`;

    // Aquí iría la lógica de rate limiting con Redis/Upstash
    // Por ahora solo passthrough
  }

  // Verificar autenticación para rutas privadas
  if (!isPublic) {
    const token =
      request.cookies.get('next-auth.session-token')?.value ||
      request.headers.get('authorization')?.replace('Bearer ', '');

    if (!token) {
      // Redirigir a login si no hay token
      if (pathname.startsWith('/api')) {
        return NextResponse.json(
          { error: 'Unauthorized' },
          { status: 401 }
        );
      }
      const loginUrl = new URL('/login', request.url);
      loginUrl.searchParams.set('callbackUrl', pathname);
      return NextResponse.redirect(loginUrl);
    }
  }

  // Añadir headers de seguridad
  const response = NextResponse.next();
  response.headers.set('X-Frame-Options', 'DENY');
  response.headers.set('X-Content-Type-Options', 'nosniff');
  response.headers.set('Referrer-Policy', 'strict-origin-when-cross-origin');

  return response;
}

export const config = {
  matcher: [
    /*
     * Match all request paths except:
     * - _next/static (static files)
     * - _next/image (image optimization files)
     * - favicon.ico (favicon file)
     * - public folder
     */
    '/((?!_next/static|_next/image|favicon.ico|public/).*)',
  ],
};
"""
