        model: data.model,
        size: data.size,
        latencyMs: Date.now() - startTime,
      };

      logHttpRequest('POST', '/api/images', 200, Date.now() - startTime);

      return apiSuccess(response);
    } catch (error) {
      logger.error({ err: error }, 'Error in /api/images');
      if (error instanceof z.ZodError) {
        return apiError('Validation error', 400, error.errors);
      }
      return apiError('Internal server error', 500);
    }
  }, 5, 60000); // 5 requests por minuto para imágenes
}
"""
