metrics_route = """// API route para métricas del dashboard
import { NextRequest } from 'next/server';
import { prisma, ensureSeed } from '@/lib/prisma';
import { apiSuccess, apiError } from '@/lib/api-utils';
import { logger, logHttpRequest } from '@/lib/logger';

export async function GET(req: NextRequest) {
  const startTime = Date.now();

  try {
    await ensureSeed();

    const { searchParams } = new URL(req.url);
    const days = parseInt(searchParams.get('days') || '30');

    // TODO: Obtener userId de la sesión
    const userId = 'demo-user';

    const since = new Date();
    since.setDate(since.getDate() - days);

    const [runs, totalTokens, totalCost] = await Promise.all([
      prisma.run.findMany({
        where: {
          userId,
          createdAt: { gte: since },
        },
        include: {
          responses: true,
        },
      }),
      prisma.run.aggregate({
        where: {
          userId,
          createdAt: { gte: since },
        },
        _sum: { tokens: true },
      }),
      prisma.run.aggregate({
        where: {
          userId,
          createdAt: { gte: since },
        },
        _sum: { cost: true },
      }),
    ]);

    // Agrupar por tipo
    const runsByType = runs.reduce(
      (acc, run) => {
        acc[run.type] = (acc[run.type] || 0) + 1;
        return acc;
      },
      {} as Record<string, number>
    );

    // Agrupar por día
    const runsByDay = runs.reduce(
      (acc, run) => {
        const date = run.createdAt.toISOString().split('T')[0];
        acc[date] = (acc[date] || 0) + 1;
        return acc;
      },
      {} as Record<string, number>
    );

    // Top modelos
    const modelCounts = runs.reduce(
      (acc, run) => {
        if (run.model) {
          acc[run.model] = (acc[run.model] || 0) + 1;
        }
        return acc;
      },
      {} as Record<string, number>
    );

    const topModels = Object.entries(modelCounts)
      .sort(([, a], [, b]) => b - a)
      .slice(0, 5)
      .map(([model, count]) => ({ model, count }));

    const avgLatency =
      runs.length > 0
        ? runs.reduce((sum, run) => sum + (run.latencyMs || 0), 0) / runs.length
        : 0;

    const response = {
      totalRuns: runs.length,
      totalTokens: totalTokens._sum.tokens || 0,
      totalCost: totalCost._sum.cost || 0,
      avgLatency: Math.round(avgLatency),
      runsByType,
      runsByDay: Object.entries(runsByDay).map(([date, count]) => ({
        date,
        count,
      })),
      topModels,
    };

    logHttpRequest('GET', '/api/metrics', 200, Date.now() - startTime);

    return apiSuccess(response);
  } catch (error) {
    logger.error({ err: error }, 'Error in /api/metrics');
    return apiError('Internal server error', 500);
  }
}
"""
(project_root / "src" / "app" / "api" / "metrics" / "route.ts").write_text(metrics_route)

