    const response = tags.map((t) => ({
      name: t.tag,
      count: t._count.tag,
    }));

    logHttpRequest('GET', '/api/tags', 200, Date.now() - startTime);

    return apiSuccess(response);
  } catch (error) {
    logger.error({ err: error }, 'Error in /api/tags');
    return apiError('Internal server error', 500);
  }
}
